<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &#39;app_id&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        =&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;KBZ_PAY_APP_ID&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>
